"""Render the privacy-notice template and DPA skeleton (SEC-11, §19.3, R30).

Run to regenerate after any change to the facts:

    cd backend/api && python -m app.compliance.render

``tests/test_compliance_docs.py`` runs the same function and compares it with the
committed files, so a stale document is a red test rather than a wrong promise.
"""

from __future__ import annotations

import sys
from pathlib import Path

from app.compliance import facts as f

REPO_ROOT = Path(__file__).resolve().parents[4]
OUT = REPO_ROOT / "docs" / "compliance"

HEADER = (
    "<!-- Generated by backend/api/app/compliance/render.py — do not edit by hand.\n"
    "     Statements marked [[FILL: ...]] are the operator's to complete. -->\n"
)


def _sub_processor_table() -> str:
    rows = [
        "| Sub-processor | Purpose | Personal data it receives | Location |",
        "|---|---|---|---|",
    ]
    for sp in f.sub_processors():
        rows.append(
            f"| {sp.label} | {sp.role} | {sp.receives} | {sp.region} |"
        )
    rows.append(
        f"| {f.fill('hosting_sub_processor')} | Infrastructure hosting: the servers "
        "that hold the database and the stored conversations | All of the above, as "
        "stored data — not as prompts | — |"
    )
    rows.append("")
    for sp in f.sub_processors():
        marker = f.provider_terms_field(sp.key)
        rows.append(
            f"- **{sp.label} terms:** {f.fill(marker)} — the provider's data-processing "
            "terms, retention statement and processing region, recorded here."
        )
    return "\n".join(rows)


def _all_tables() -> str:
    rows = ["| Table | Contents | Retention |", "|---|---|---|"]
    for table in f.TABLES:
        rows.append(f"| `{table.name}` | {table.purpose} | {table.retention} |")
    return "\n".join(rows)


def render_privacy_notice() -> str:
    r = f.retention_facts()
    e = f.egress_facts()
    hours = f"{r.purge_hour:02d}:{r.purge_minute:02d}"
    types = ", ".join(e.upload_types)
    mb = e.upload_bytes // (1024 * 1024)
    body = f"""{HEADER}
# Privacy notice — template for businesses using this assistant

> **How to use this template.** It is written for the business that embeds the
> assistant on its own website. That business is the **data controller**: it decides
> what the assistant is for and whose questions it answers. Complete every
> `[[FILL: ...]]` marker, keep the factual statements as they are, and publish the
> result where visitors can read it before they start a chat.
>
> The statements below describe what the software actually does. They are generated
> from the code that implements the behaviour, and a test fails if this file drifts
> from it — so do not "improve" a number or a table here; change the code instead, or
> the document becomes a claim nobody can keep.

## 1. Who is responsible for your information

{f.fill("business_legal_name")}, {f.fill("business_address")}, is the controller of
the personal data described here. Privacy contact: {f.fill("business_contact")}.

The assistant runs on a platform operated by {f.fill("platform_legal_name")}, which
processes that data on the business's behalf under a data processing agreement.

## 2. What the assistant collects

Only what a conversation needs, and only once you open the chat. Before you open it,
the assistant stores nothing on your device and creates nothing on the server.

| What | When | Why |
|---|---|---|
| Your messages to the assistant | When you send them | To answer your question |
| The assistant's answers, with the sources they were drawn from | When it answers | To show you the answer and where it came from |
| The page address you were on when the chat started | When the conversation starts | So the team knows what you were looking at |
| A random session identifier for this browser tab | When the conversation starts | To keep one conversation together; it is not a cookie and it is not used to identify you across sites |
| Your name and email address | Only if you choose to leave them to ask for a person to follow up | So the business can reply to you |
| A thumbs-up or thumbs-down, and any comment you add | Only if you rate an answer | So the business can improve its answers |
| Attachments you add, if the assistant offers that | Only if you attach one | Up to {mb} MB, restricted to {types}. The type is verified from the file's contents. **The file's name, type and size are recorded and the file itself is not kept or opened** — nothing reads your attachment, by design |
| A confidence score and the sources behind each answer | Automatically, with each answer | So the business can tell which of its answers are weak |

The assistant does not ask for, and does not need, identity documents, payment card
details, health information or anything else sensitive. Please do not send them.

## 3. Why we are allowed to process it

- **Answering your question** — the business's legitimate interest in supporting its
  own customers, or your request before entering into a contract.
- **Following up when you ask for a person** — your consent, given by leaving your
  contact details, or steps taken at your request.
- **Keeping the service secure and working** — the business's legitimate interest in
  preventing abuse.

{f.fill("legal_basis_review")} — confirm the basis for your own jurisdiction and
sector before publishing.

## 4. How long it is kept

The business sets a retention period for conversations: **{r.default_days} days** by
default, configurable between {r.minimum_days} and {r.maximum_days}. A job runs daily at
{hours} by the worker's own clock and deletes conversations that are finished —
{' or '.join(f'`{s}`' for s in r.eligible_statuses)} — once they have passed that
window, which is measured from {r.aged_on}. A conversation still in progress is never
deleted.

Deleting a conversation deletes its messages, its ratings and comments, its handover
record and its attachment metadata with it.

## 5. Who else sees it

The assistant needs a language model to compose an answer, so your messages are sent
to the model providers listed first below. The hosting provider holds the stored data
but does not compose answers. These are the only parties that receive the content of a
conversation.

{_sub_processor_table()}

What is sent for an ordinary question: your message, up to the last
{e.history_messages} messages of the conversation, and up to {e.max_chunk_chars}
characters from each of the business's own knowledge-base passages retrieved for it.
The business's bot instructions are sent too, because they tell the model how to
answer. For a handover summary it is the compiled transcript, including your name,
email address and the page address where you supplied them.

The business's own uploaded documents are indexed by an embedding model that runs
inside the platform, not at a third party.

## 6. Where it is processed

The platform's servers are located in {f.fill("hosting_location")}. A model provider may
process a prompt outside the EU; where it does, the transfer is covered by that
provider's own safeguards, as recorded in the table above. This is disclosed rather
than claimed away.

## 7. What you can ask for

- **A copy** of everything held about a conversation, including the transcript, every
  message, every rating, the handover record and your identifiers, as a text or JSON
  file.
- **Deletion** of a conversation and the identifiers attached to it. This is
  immediate and does not wait for the retention period to expire.
- **Correction** of your name or email address, by asking the business.
- **Objection or restriction**, and **withdrawal of consent** for the follow-up
  contact, at any time.

Ask the business at {f.fill("business_contact")}. The business can produce the copy
itself from its dashboard; deletion is performed by the platform operator on the
business's instruction, using the erasure operation the software provides. The
business does not have to ask the model providers, and neither does the visitor.

One limit, stated rather than hidden: the platform keeps an append-only audit log of
account and administrative actions, which records that a conversation was erased —
counts and the conversation identifier, never your name, address or the pages you
visited. That record exists to prove the erasure happened and is not deleted.

## 8. Cookies and storage on your device

Before you open the chat: nothing. No cookie, no local storage entry, nothing read or
written. This is audited in a real browser as part of the release process.

After you open the chat, two session-scoped values are written, and both are gone when
the tab closes: a random conversation identifier (`eva_conversation`) and the random
visitor identifier (`eva_visitor`). Neither is a tracking cookie and neither is shared
with anyone.

If you choose to be recognised on your next visit, one durable marker
(`eva_visitor_durable`) is stored in your browser's local storage, and only after you
opt in. You can clear it at any time by clearing site data.

The dashboard used by the business's own staff sets a login cookie
(`eva_session`). It is not present on the business's public site.

## 9. Automated answers

The assistant is an AI system and says so in the chat window. Its answers are drawn
only from the business's published information; when it cannot find a confident answer
it says so and offers to pass the question to a person. It cannot take actions — no
refunds, no order changes, no emails sent on your behalf. You can ask for a human at
any point.

## 10. Complaints

If you are unhappy with how your information was handled, tell the business first at
{f.fill("business_contact")}. You also have the right to complain to a data protection
supervisory authority, in the country where you live or work or where the business is
established.

## 11. Changes

{f.fill("effective_date")} — the date this notice takes effect. Material changes are
announced on this page before they apply.

---

*US state privacy law disclosures (including the CCPA/CPRA categories, the "do not
sell or share" position and statutory response windows) are a separate template and
are not claimed by this document.*
"""
    return body


def render_dpa() -> str:
    from app.config import SESSION_TTL_SECONDS

    r = f.retention_facts()
    hours = f"{r.purge_hour:02d}:{r.purge_minute:02d}"
    session_hours = SESSION_TTL_SECONDS // 3600
    body = f"""{HEADER}
# Data processing agreement — skeleton

> **What this is.** A skeleton, not an executed contract. It fixes the *factual*
> positions the software enforces — who is controller, who is processor, which
> sub-processors exist, what is retained and for how long, what security controls are
> actually implemented — so that a lawyer can complete the legal terms around them
> without having to rediscover them.
>
> Complete every `[[FILL: ...]]` marker. Do not soften a technical statement to match a
> template you have seen elsewhere: each one below is a behaviour of the code, and a
> test fails if this file and the code disagree.

## 1. Parties and roles

- **Controller:** {f.fill("business_legal_name")}, {f.fill("business_address")} ("the
  Business"). It decides the purposes and means of the processing.
- **Processor:** {f.fill("platform_legal_name")}, {f.fill("platform_address")} ("the
  Processor"). It processes personal data only on the Business's documented
  instructions.

**Open decision D3.** The platform treats the Business as controller and itself as
processor, with model providers as its sub-processors (§19.3). Whether the Processor
should instead be described as a sub-processor in a longer chain — where the Business's
own hosting or agency sits above it — is unresolved and is recorded as
`docs/ARCHITECTURE.md` D3. The description above is the position the software
implements; {f.fill("d3_position")} if a chain description is required instead.

## 2. Subject matter, duration, nature and purpose

- **Subject matter:** operating an AI customer-support assistant embedded on the
  Business's website.
- **Purpose:** answering visitors' questions from the Business's own knowledge base,
  showing the sources of an answer, collecting a satisfaction rating, and notifying
  the Business when a visitor asks for a person.
- **Duration:** the term of the Business's agreement with the Processor, plus the
  deletion obligations in §7.
- **Nature:** collection, storage, retrieval, transmission to sub-processors for
  prompt completion, and deletion.

## 3. Categories of data and of data subjects

- **Data subjects:** the Business's website visitors who open the chat; the Business's
  own staff who use the dashboard.
- **Personal data:** conversation content (questions and answers), the page address,
  a random per-tab session identifier, and — only when the visitor supplies them — the
  visitor's name, email address and file attachments; ratings and optional comments;
  handover records; for staff, login email, password hash, session metadata and IP
  address.

Special-category data is neither requested nor required. The Business must not
instruct the Processor to process it; where a visitor volunteers it in free text, the
Processor treats it no differently from the rest of the conversation.

## 4. The Processor's obligations

The Processor shall:

1. process personal data only on the Business's documented instructions, including for
   transfers to a third country, unless required otherwise by law — and then only after
   informing the Business, unless the law forbids that;
2. ensure that persons authorised to process the data are bound by confidentiality;
3. implement the technical and organisational measures in §6;
4. assist the Business in responding to data-subject requests. Two operations exist and
   only one is a dashboard control, stated plainly rather than smoothed over: the
   Business produces a complete per-conversation export itself from its dashboard,
   while erasure of a conversation and its identifiers is an API operation the
   Processor performs on the Business's instruction — no dashboard control deletes a
   conversation (§7);
5. notify the Business without undue delay, and in any event within
   {f.fill("breach_notice_window")}, after becoming aware of a personal-data breach;
6. assist the Business with data-protection impact assessments and prior consultations,
   taking into account the nature of the processing;
7. delete or return all personal data at the end of the provision of services (§7);
8. make available the information needed to demonstrate compliance, and allow audits
   (§8).

## 5. Sub-processors

The Business authorises the following sub-processors. The model providers receive
conversation content only to compose an answer or a handover summary; the host stores
the data and is not given prompts to process.

{_sub_processor_table()}

- The Processor will give the Business notice of any intended change concerning the
  addition or replacement of a sub-processor, with an opportunity to object.
- A sub-processor is bound by data-protection obligations no less protective than
  these terms.
- Model providers are chosen at the platform level, not per tenant; the table is the
  complete list of parties that can receive conversation content.

## 6. Security measures

These describe the code in this repository, not an aspiration. Where a control is
partly the operator's to provide, it says so instead of claiming it.

| Measure | How it works here |
|---|---|
| Tenant isolation | PostgreSQL row-level security on every table that holds tenant data, plus an explicit tenant predicate in every query as defence in depth. Cross-tenant reads answer "not found" rather than "forbidden", so an identifier cannot be probed |
| Encryption in transit | TLS terminated at the reverse proxy |
| Encryption at rest | Model-provider keys are encrypted with `age` (X25519 + ChaCha20-Poly1305) in files outside the database, and only a reference path is stored. Encryption of the database volume itself is **not implemented in the application** and is the operator's to provide: {f.fill("database_at_rest")} |
| Credential handling | Business-supplied provider keys are write-only: no API response has a field capable of returning one, and the dashboard shows only the last four characters |
| Password storage | Argon2id at OWASP parameters; only a hash is stored |
| Session security | Server-side sessions in the database with only a SHA-256 of the cookie value stored; the cookie is HTTP-only, SameSite=Lax and Secure wherever TLS terminates in front; sessions expire {session_hours} hours after login, are revoked on logout, and are deleted with the account |
| Abuse limits | Per-visitor, per-IP and per-tenant rate limits on widget endpoints; per-user limits on the dashboard |
| Widget origin control | A widget serves only on origins the Business has verified; the token is signed and short-lived |
| Untrusted content | Retrieved knowledge-base text and visitor messages are treated as data, never as instructions, when a prompt is composed |
| Uploads | Type verified from the bytes, not the filename or the claimed type; a size cap enforced while the body is streamed; nothing parsed on upload; uploaded bytes never served back |
| Audit trail | Every administrative mutation is recorded in an append-only log that cannot be updated or deleted, including erasure events (counts and identifiers only) |

## 7. Retention, deletion and return

- Conversations are retained for the Business's configured window, **default
  {r.default_days} days**, configurable between {r.minimum_days} and
  {r.maximum_days}. A job runs daily at {hours} by the worker's own clock and deletes finished
  conversations — {' or '.join(f'`{s}`' for s in r.eligible_statuses)} — once they pass
  the window, measured from {r.aged_on}.
- Deleting a conversation deletes its messages, ratings, handover record and
  attachment metadata through the database's own cascade. No copy of the content
  remains in a business table.
- A data-subject erasure request takes precedence over the retention window: it is
  immediate and applies to a conversation in any state.
- Usage totals survive an erasure with their link to the conversation set to null, so
  the Business's cost history holds no path back to a visitor.
- The append-only audit log survives, by design, and records erasure as counts and the
  conversation identifier only. It never contains the visitor's name, address, session
  identifier or page address.
- **Backups.** Backup retention is {f.fill("backup_retention")}. Until the restore drill
  is complete and timed, this agreement must not claim a backup regime; a deletion
  request that must reach backups needs a documented restore-and-redact procedure, which
  is not yet implemented.
- At the end of the agreement, personal data is deleted or returned as the Business
  directs, subject to the audit log and to any legal retention obligation.

## 8. Audits

The Processor makes available the information needed to demonstrate compliance with
this agreement. Where an audit is agreed, it is conducted with reasonable prior notice,
during business hours, subject to confidentiality, and at the Business's cost where it
exceeds what is required by law. The test suite and the append-only audit log are the
primary evidence.

## 9. Liability, term and governing law

- Liability: {f.fill("liability")}.
- Term: from the effective date until the agreement ends and the deletion obligations
  in §7 are discharged.
- Governing law and jurisdiction: {f.fill("governing_law")}.
- Precedence: where this skeleton and the main services agreement conflict on a
  data-protection matter, this skeleton prevails.
- Effective date: {f.fill("effective_date")}.

---

### Appendix A — Complete data inventory

Every table the software creates, including those that hold no personal data. The list
is checked against the database migrations, so a new table cannot be added without
appearing here.

{_all_tables()}
"""
    return body


def render_all() -> dict[str, str]:
    return {
        "privacy-notice-template.md": render_privacy_notice(),
        "dpa-skeleton.md": render_dpa(),
    }


def main(argv: list[str]) -> int:
    OUT.mkdir(parents=True, exist_ok=True)
    for name, content in render_all().items():
        (OUT / name).write_text(content, encoding="utf-8")
        print(f"wrote {OUT / name}")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
